import math

def validate_reset_token(submitted_token, user_id, record, now):
    if not isinstance(submitted_token, str) or not submitted_token:
        return False
    if not isinstance(record, dict):
        return False
    token = record.get("token")
    owner = record.get("user_id")
    exp = record.get("expires_at")
    if not isinstance(token, str) or not token:
        return False
    if not isinstance(exp, (int, float)) or isinstance(exp, bool):
        return False
    if not isinstance(now, (int, float)) or isinstance(now, bool):
        return False
    if not math.isfinite(exp) or not math.isfinite(now):
        return False
    if submitted_token != token or user_id != owner:
        return False
    if now >= exp:
        return False
    return True
